// Foundry 13+ passes HTMLElement; older sheets still pass jQuery.
function swffgRoot(html) { return html?.querySelector ? html : html?.[0]; }
function swffgHeading(html, text, selector, className = "swffgui") {
    const root = swffgRoot(html);
    if (!root || root.querySelector(`.${className}`)) return;
    const section = document.createElement("section");
    section.className = className;
    const heading = document.createElement("h3");
    heading.className = "auberesh";
    heading.textContent = text;
    section.append(heading);
    const anchor = root.querySelector(selector);
    if (anchor) anchor.before(section); else root.prepend(section);
}
for (const [hook, title, selector] of [
    ["renderActorDirectory", "Actors Directory", ".directory-header"],
    ["renderSceneDirectory", "Scenes Directory", ".directory-header"],
    ["renderJournalDirectory", "Journal Directory", ".directory-header"],
    ["renderItemDirectory", "Items Directory", ".directory-header"],
