    ["renderChatLog", "Chat Log", "#chat-log"],
    ["renderCombatTracker", "Combat Tracker", "#combat-tracker"],
    ["renderSettings", "Settings", "h2"],
    ["renderSettingsConfig", "Configure Game Settings", "section"]
]) Hooks.on(hook, (app, html) => swffgHeading(html, title, selector));

