// Remove only this module's templates from the token's own scene.
async function clearTokenRangeBands(tokenDocument) {
  if (!game.user.isGM || (game.users.activeGM && game.users.activeGM.id !== game.user.id)) return;
  const scene = tokenDocument.parent;
  if (!scene?.templates) return;
  const ids = scene.templates.filter(t=>t.flags["lgs-token-range-bands"]?.tokenId === tokenDocument.id).map(t=>t.id);
  if (ids.length) await scene.deleteEmbeddedDocuments("MeasuredTemplate", ids);
}
Hooks.on("updateToken", (token, changes)=>{
  if ("x" in changes || "y" in changes) return clearTokenRangeBands(token);
});
Hooks.on("moveToken", clearTokenRangeBands);
Hooks.on("deleteToken", clearTokenRangeBands);

